> 用chan实现，不做什么讲解了

### 题目

实现一个Map，要求：
 (1) 支持高并发；
 (2) 只要求插入查询操作，O（1）；
 (3) 查询时，存在则返回value；否则，等待一个超时时间后返回错误；
 (4) 运行不存在死锁、panic；

### 实现

```Go
type ConcurrentMap struct {
	sync.Mutex
	mp      map[any]any
	keyChan map[any]chan struct{}
}

func NewConcurrentMap() *ConcurrentMap {
	return &ConcurrentMap{
		mp:      make(map[any]any),
		keyChan: make(map[any]chan struct{}),
	}
}

func (m *ConcurrentMap) Put(k, v any) {
	m.Lock()
	defer m.Unlock()

	// 正常写入
	m.mp[k] = v

	// 给正在等的携程一个信号
	ch, ok := m.keyChan[k]
	if ok {
		close(ch)
		delete(m.keyChan, k) // 关键：删除已关闭的通道，避免后续重复操作
	}
}

func (m *ConcurrentMap) Get(k any, timeout time.Duration) (any, error) {
	m.Lock()
	// key存在：直接返回
	v, ok := m.mp[k]
	if ok {
		m.Unlock()
		return v, nil
	}

	// key不存在：等待（阻塞）一段时间
	ch, ok := m.keyChan[k]
	if !ok {
		// 这样没法赋值
		// m.keyChan[k] = make(chan struct{})
		ch = make(chan struct{})
		m.keyChan[k] = ch
	}
	// 要先解锁，否则put携程没法拿到ch
	m.Unlock()

	tCtx, cancel := context.WithTimeout(context.Background(), timeout)
	defer cancel()

	select {
	case <-ch:
		m.Lock()
		v := m.mp[k]
		m.Unlock()
		return v, nil
	case <-tCtx.Done():
		return nil, tCtx.Err()
	}
}

```
